// Syncs the extension with the DevTools app's tool registry:
// - src/tools.json: the fallback list for Search Tools (used when the app has not written its own).
// - One Raycast command per tool, so typing a tool name in Raycast's root search opens it.
//   Each command is a small generated file src/tool-<id>.ts plus an entry in package.json.
// Usage: npm run sync-tools -- [path to the devtools repo]   (default: ../devtools)
import { execFileSync } from "node:child_process";
import { readFileSync, readdirSync, unlinkSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = new URL("..", import.meta.url).pathname;
const appRepo = path.resolve(process.argv[2] ?? "../devtools");
const registry = readFileSync(path.join(appRepo, "src/app/toolRegistry.ts"), "utf8");
const entry =
  /\{\s*icon:\s*\w+,\s*name:\s*"([^"]+)",\s*id:\s*"([^"]+)",\s*category:\s*"([^"]+)"(?:,\s*keywords:\s*\[([^\]]*)\])?\s*\}/g;
const tools = [...registry.matchAll(entry)].map(([, name, id, category, keywords = ""]) => ({
  id,
  name,
  category,
  keywords: [...keywords.matchAll(/"([^"]+)"/g)].map(([, keyword]) => keyword),
}));

if (tools.length === 0) {
  throw new Error(`No tools found in ${appRepo}/src/app/toolRegistry.ts. Check the path.`);
}

const toolsJson = path.join(root, "src/tools.json");
writeFileSync(toolsJson, `${JSON.stringify(tools, null, 2)}\n`);

// Per-tool command files. Remove ones for tools that no longer exist.
const srcDir = path.join(root, "src");
for (const file of readdirSync(srcDir)) {
  if (/^tool-.+\.ts$/.test(file)) unlinkSync(path.join(srcDir, file));
}
for (const tool of tools) {
  writeFileSync(
    path.join(srcDir, `tool-${tool.id}.ts`),
    `// Generated by scripts/sync-tools.mjs. Do not edit.\nimport { openTool } from "./lib/open-tool";\n\nexport default async function Command() {\n  await openTool(${JSON.stringify(tool.id)});\n}\n`,
  );
}

// package.json: keep the hand-written commands first, then one command per tool.
const pkgPath = path.join(root, "package.json");
const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
const fixed = pkg.commands.filter((command) => !command.name.startsWith("tool-"));
pkg.commands = [
  ...fixed,
  ...tools.map((tool) => ({
    name: `tool-${tool.id}`,
    title: tool.name,
    subtitle: "DevTools",
    description: `Open ${tool.name} in DevTools.`,
    mode: "no-view",
    keywords: tool.keywords.slice(0, 10),
  })),
];
writeFileSync(pkgPath, `${JSON.stringify(pkg, null, 2)}\n`);

// Match the repo's Prettier style so that ray lint passes after a sync.
execFileSync("npx", ["prettier", "--write", toolsJson, pkgPath, path.join(srcDir, "tool-*.ts")], { stdio: "ignore" });
console.log(`Wrote ${tools.length} tools: src/tools.json, ${tools.length} commands in package.json and src/tool-*.ts.`);
